const fs = require('fs');
const backupPath = '/backups';

let isBackupValid = false;
let statusMessage = '';
let latestFile = 'N/A';
let fileSizeMB = '0';
let fileAgeHours = '999';

try {
  if (fs.existsSync(backupPath)) {
    const files = fs.readdirSync(backupPath).filter(f => f.endsWith('.dump') || f.endsWith('.sql'));
    if (files.length > 0) {
      const stats = files.map(file => {
        const stat = fs.statSync(`${backupPath}/${file}`);
        return { file, mtime: stat.mtime, size: stat.size };
      }).sort((a, b) => b.mtime - a.mtime);

      const latest = stats[0];
      latestFile = latest.file;
      fileSizeMB = (latest.size / (1024 * 1024)).toFixed(2);
      fileAgeHours = ((new Date() - new Date(latest.mtime)) / (1000 * 60 * 60)).toFixed(2);

      if (parseFloat(fileAgeHours) <= 25 && latest.size > 0) {
        isBackupValid = true;
        statusMessage = `Backup correcto: ${latestFile} (${fileSizeMB} MB, generado hace ${fileAgeHours}hs).`;
      } else {
        statusMessage = `ALERTA: El backup ${latestFile} está desactualizado (${fileAgeHours}hs) o corrupto.`;
      }
    } else {
      statusMessage = 'ALERTA CRÍTICA: No se encontraron archivos de backup (.dump / .sql) en /backups.';
    }
  } else {
    statusMessage = 'ALERTA CRÍTICA: El directorio /backups no existe o no está montado en n8n.';
  }
} catch (error) {
  statusMessage = `Error al verificar backups: ${error.message}`;
}

return [{
  json: {
    isBackupValid,
    statusMessage,
    latestFile,
    fileSizeMB,
    fileAgeHours,
    alertname: 'PostgresBackupVerification',
    severity: isBackupValid ? 'info' : 'critical',
    mantisPriority: 'high',
    mantisSeverity: 'major'
  }
}];

